only = sys.argv[1] if len(sys.argv) > 1 else ''
labels = None                                    # WB_LABELS=file: run exactly the mutants whose labels are listed there, one per line
if os.environ.get('WB_LABELS'): labels = set(l.strip() for l in open(os.environ['WB_LABELS']) if l.strip())
def run(tests):
    r = subprocess.run('python3 -m pytest -q -x ' + tests, shell=True, capture_output=True, text=True, timeout=900)
    out = r.stdout + r.stderr
    failed = [l.split('::')[-1].split(' ')[0] for l in out.splitlines() if l.startswith('FAILED ')]
    return r.returncode != 0, (failed[0] if failed else 'error'), ('Timeout' in out or 'timed out' in out)
killed=0; surv=[]; bad=[]; flaky=[]
for label,f,old,new,tests in M:
    if only and only not in label: continue
    if labels is not None and label not in labels: continue
    src=open(f,newline='').read()
    if src.count(old)!=1: bad.append((label, src.count(old))); continue
    open(f,'w',newline='').write(src.replace(old,new))
    try:
        dead, where, waited = run(tests)
        # A browser test that fails by running out of time may only have been slow (a busy PC): the kill counts if it fails a second time.
        if dead and waited:
            dead2, where2, _ = run(tests)
            if not dead2: flaky.append(label); print('FLAKY    %s (failed once in %s, then passed)' % (label, where), flush=True); continue
        if dead: killed+=1; print('killed   %-60s %s' % (label, where), flush=True)
        else: surv.append(label); print('SURVIVED', label, flush=True)
    finally:
        open(f,'w',newline='').write(src)
print(killed,'killed',len(surv),'survived',len(flaky),'flaky',len(bad),'unusable'); print(surv, flaky, bad)
